 "content": "def transform(grid):
    """Tile the 8-cells with 2x2 squares and L-triominoes, then color pieces.

    In both demonstrations, each 2x2 square is color 1. Each L triomino's
    color is determined by its missing corner in its 2x2 bounding box:
    missing lower-right -> 2; missing upper-right -> 3; missing upper-left -> 4.
    The demo structures are uniquely tileable under this piece set.
    """
    h, w = len(grid), len(grid[0])
    ink = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r,c), (r+1,c), (r,c+1), (r+1,c+1)}
            if box <= ink:
                pieces.append((box, 1))
            missing_corner_color = {
                (r,c): 2, (r,c+1): 4,
                (r+1,c): 3, (r+1,c+1): 1,
            }
            for missing in box:
                tri = box - {missing}
                if tri <= ink:
                    pieces.append((tri, missing_corner_color[missing]))

    # Exact-cover search. Prefer larger pieces only for deterministic order;
    # do not depend on that preference for the result.
    by_cell = {cell: [] for cell in ink}
    for piece, color in pieces:
        for cell in piece:
            by_cell[cell].append((piece, color))
    solutions = []
    def search(remaining, chosen):
        if not remaining:
            solutions.append(chosen[:])
            return
        cell = min(remaining, key=lambda p: sum(piece <= remaining for piece, _ in by_cell[p]))
        for piece, color in by_cell[cell]:
            if piece <= remaining:
                search(remaining - piece, chosen + [(piece, color)])
                if len(solutions) > 1:
                    return
    search(ink, [])
    if len(solutions) != 1:
        raise ValueError("8-cells do not have a unique square/L-triomino tiling")
    out = [row[:] for row in grid]
    for solution in solutions[0]:
        piece, color = solution
        for r, c in piece:
            out[r][c] = color
    return out
